// ════════════════════════════════════════════════════════════════
export default function App() {
  const [users, setUsers] = useState([]);
  const [items, setItems] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [savedAddresses, setSavedAddresses] = useState([]);
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(true);

  // Load all data from Supabase on startup
  useEffect(() => {
    const loadAll = async () => {
      setLoading(true);
      try {
        const [dbUsers, dbItems, dbRooms, dbAddresses] = await Promise.all([
          db.getUsers(), db.getItems(), db.getRooms(), db.getAddresses()
        ]);

        // Seed admin user if no users exist
        if (!dbUsers || dbUsers.length === 0) {
          await db.addUser({ id:"u0", username:"admin", password:"admin123", name:"Admin", role:"admin" });
          setUsers([{ id:"u0", username:"admin", password:"admin123", name:"Admin", role:"admin" }]);
        } else {
          setUsers(dbUsers);
        }

        // Seed default rooms if none exist
        if (!dbRooms || dbRooms.length === 0) {
          for (const r of INITIAL_ROOMS) await db.addRoom(r);
          setRooms(INITIAL_ROOMS);
        } else {
          setRooms(dbRooms.map(r => r.name));
        }

        setItems(dbItems || []);
        setSavedAddresses((dbAddresses || []).map(a => a.address));
      } catch(e) {
        console.error("Load error:", e);
      }
      setLoading(false);
    };
    loadAll();
  }, []);

  const login = (username, password) => {
    const u = users.find(u => u.username === username && u.password === password);
    if (!u) return false;
    setSession({ user: u });
    return true;
  };
  const logout = () => setSession(null);

  if (loading) return (
    <div style={{ minHeight:"100vh", background:C.bg, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", fontFamily:"Georgia,serif" }}>
      <Logo height={120} />
      <div style={{ marginTop:24, fontSize:13, color:C.textMid, letterSpacing:"0.1em" }}>Loading inventory…</div>
    </div>
  );

  if (!session) return <LoginScreen onLogin={login} />;
  if (session.user.role === "worker") return <WorkerView session={session} items={items} setItems={setItems} rooms={rooms} savedAddresses={savedAddresses} setSavedAddresses={setSavedAddresses} onLogout={logout} db={db} />;
  return <AdminView session={session} items={items} setItems={setItems} users={users} setUsers={setUsers} rooms={rooms} setRooms={setRooms} savedAddresses={savedAddresses} setSavedAddresses={setSavedAddresses} onLogout={logout} db={db} />;
}

// ════════════════════════════════════════════════════════════════
// LOGIN
// ════════════════════════════════════════════════════════════════
function LoginScreen({ onLogin }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = () => {
    setLoading(true); setError("");
    setTimeout(() => {
      if (!onLogin(username.trim(), password)) { setError("Invalid username or password."); setLoading(false); }
    }, 500);
  };

  return (
    <div style={{ minHeight:"100vh", background:C.bg, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:24, fontFamily:"'Georgia', serif" }}>
      {/* Decorative top line */}
      <div style={{ width:60, height:2, background:C.gold, marginBottom:32 }} />

      <Logo height={160} />

      <div style={{ width:1, height:32, background:C.border, margin:"24px auto" }} />

      <p style={{ margin:"0 0 32px", color:C.textMid, fontSize:12, letterSpacing:"0.18em", textTransform:"uppercase" }}>
        Inventory Management
      </p>

      <div style={{ width:"100%", maxWidth:360, background:C.surface, border:`1px solid ${C.border}`, borderRadius:12, padding:32, boxShadow:"0 8px 40px rgba(0,0,0,0.07)" }}>
        <div style={{ marginBottom:18 }}>
          <label style={S.label}>Username</label>
          <input value={username} onChange={e=>setUsername(e.target.value)} placeholder="Enter your username"
            style={S.input} onKeyDown={e=>e.key==="Enter"&&submit()} />
        </div>
        <div style={{ marginBottom:24 }}>
          <label style={S.label}>Password</label>
          <input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password"
            style={S.input} onKeyDown={e=>e.key==="Enter"&&submit()} />
        </div>
        {error && <div style={{ color:C.red, fontSize:12, marginBottom:16, textAlign:"center", letterSpacing:"0.02em" }}>{error}</div>}
        <button onClick={submit} disabled={loading} style={{ ...S.btnPrimary, width:"100%", padding:"13px", fontSize:13, opacity:loading?0.7:1 }}>
          {loading ? "Signing in…" : "Sign In"}
        </button>


      </div>

      <div style={{ width:60, height:2, background:C.gold, marginTop:32 }} />
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// WORKER VIEW
// ════════════════════════════════════════════════════════════════
function WorkerView({ session, items, setItems, rooms, savedAddresses, setSavedAddresses, onLogout, db }) {
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("All");
  const [selected, setSelected] = useState(null);
  const [checkoutItemId, setCheckoutItemId] = useState(null);
  const [workerTab, setWorkerTab] = useState("inventory");

  const filtered = items.filter(it =>
    (filter==="All"||it.room===filter) &&
    it.name.toLowerCase().includes(search.toLowerCase())
  );

  const confirmCheckout = async (id, address) => {
    const ts = new Date().toLocaleString();
    const item = items.find(i=>i.id===id);
    const newLog = [...(item?.log||[]), { action:"Checked Out", by:session.user.name, at:ts, address }];
    await db.updateItem(id, { status:"out", address, log:newLog });
    if (address && !savedAddresses.includes(address)) {
      await db.addAddress(address);
      setSavedAddresses(prev => [address, ...prev].slice(0, 10));
    }
    setItems(prev => prev.map(it => it.id===id ? { ...it, status:"out", address, log:newLog } : it));
    setCheckoutItemId(null);
  };

  const markReturn = async (id) => {
    const ts = new Date().toLocaleString();
    const item = items.find(i=>i.id===id);
    const newLog = [...(item?.log||[]), { action:"Returned", by:session.user.name, at:ts }];
    await db.updateItem(id, { status:"in", address:null, log:newLog });
    setItems(prev => prev.map(it => it.id===id ? { ...it, status:"in", address:null, log:newLog } : it));
  };

  const handleAction = (id, newStatus) => {
    if (newStatus === "out") { setCheckoutItemId(id); return; }
    markReturn(id);
  };

  const item = selected ? items.find(i=>i.id===selected.id) : null;

  return (
    <div style={{ minHeight:"100vh", background:C.bg, fontFamily:"'Georgia', serif", color:C.text }}>
      <Header name={session.user.name} role="Worker" onLogout={onLogout}>
        <nav style={{ display:"flex", gap:6 }}>
          {[["inventory","Inventory"],["scan","Scan QR"]].map(([key,label])=>(
            <button key={key} onClick={()=>{ setWorkerTab(key); setSelected(null); }} style={{
              padding:"7px 18px", borderRadius:6, cursor:"pointer", fontSize:12, fontFamily:"'Georgia',serif",
              letterSpacing:"0.06em", border:`1px solid ${workerTab===key?C.charcoal:C.border}`,
              background: workerTab===key?C.charcoal:"transparent",
              color: workerTab===key?"#faf7f4":C.textMid,
            }}>{label}</button>
          ))}
        </nav>
      </Header>

      <div style={{ maxWidth:680, margin:"0 auto", padding:"24px 20px" }}>
        {workerTab==="scan" ? (
          <QRScanTab items={items} session={session} onAction={handleAction} savedAddresses={savedAddresses} onCheckout={(id,addr)=>confirmCheckout(id,addr)} />
        ) : item ? (
          <>
            <button onClick={()=>setSelected(null)} style={{ ...S.ghost, marginBottom:20, fontSize:12 }}>← Back to Inventory</button>
            <ItemDetailCard item={item} isWorker onAction={handleAction} />
          </>
        ) : (
          <>
            <SearchBar search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} rooms={rooms} />
            <div style={{ display:"flex", flexDirection:"column", gap:8, marginTop:16 }}>
              {filtered.map(it => <ItemRow key={it.id} item={it} onClick={()=>setSelected(it)} />)}
              {filtered.length===0 && <EmptyState />}
            </div>
          </>
        )}
      </div>

      {checkoutItemId && (
        <CheckoutModal
          itemName={items.find(i=>i.id===checkoutItemId)?.name}
          savedAddresses={savedAddresses}
          onConfirm={(addr) => confirmCheckout(checkoutItemId, addr)}
          onCancel={() => setCheckoutItemId(null)}
        />
      )}
    </div>
  );
}

function CheckoutModal({ itemName, savedAddresses, onConfirm, onCancel }) {
  const [tab, setTab] = useState(savedAddresses.length > 0 ? "saved" : "new");
  const [newAddress, setNewAddress] = useState("");
  const [selectedSaved, setSelectedSaved] = useState(savedAddresses[0] || "");

  const handleConfirm = () => {
    const addr = tab === "new" ? newAddress.trim() : selectedSaved;
    if (!addr) return;
    onConfirm(addr);
  };

  const canConfirm = tab === "new" ? newAddress.trim().length > 0 : !!selectedSaved;

  return (
    <div style={{ position:"fixed",inset:0,background:"rgba(28,25,23,0.55)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:200,padding:20 }}>
      <div style={{ background:C.surface,borderRadius:12,padding:28,width:"100%",maxWidth:420,border:`1px solid ${C.border}`,boxShadow:"0 16px 60px rgba(0,0,0,0.15)" }}>
        <div style={{ marginBottom:20 }}>
          <h3 style={{ margin:"0 0 5px", fontSize:17, fontWeight:700 }}>Check Out Item</h3>
          <p style={{ margin:0, fontSize:12, color:C.textMid }}>Where is <strong>{itemName}</strong> being taken?</p>
        </div>

        {/* Tabs */}
        <div style={{ display:"flex", marginBottom:20, border:`1px solid ${C.border}`, borderRadius:8, overflow:"hidden" }}>
          {savedAddresses.length > 0 && (
            <button onClick={()=>setTab("saved")} style={{ flex:1, padding:"9px", border:"none", borderRight:`1px solid ${C.border}`, background:tab==="saved"?C.charcoal:"transparent", color:tab==="saved"?"#faf7f4":C.textMid, cursor:"pointer", fontFamily:"'Georgia',serif", fontSize:12, fontWeight:600, letterSpacing:"0.04em" }}>
              Saved Addresses
            </button>
          )}
          <button onClick={()=>setTab("new")} style={{ flex:1, padding:"9px", border:"none", background:tab==="new"?C.charcoal:"transparent", color:tab==="new"?"#faf7f4":C.textMid, cursor:"pointer", fontFamily:"'Georgia',serif", fontSize:12, fontWeight:600, letterSpacing:"0.04em" }}>
            New Address
          </button>
        </div>

        {tab === "saved" && (
          <div style={{ display:"flex", flexDirection:"column", gap:8, marginBottom:20, maxHeight:220, overflowY:"auto" }}>
            {savedAddresses.map((addr, i) => (
              <div key={i} onClick={()=>setSelectedSaved(addr)} style={{
                padding:"11px 14px", borderRadius:8, cursor:"pointer",
                border:`1px solid ${selectedSaved===addr?C.gold:C.border}`,
                background:selectedSaved===addr?`${C.gold}18`:C.bgDeep,
                fontSize:13, color:C.text, transition:"border-color .15s",
                display:"flex", alignItems:"center", gap:10,
              }}>
                <span style={{ fontSize:16 }}>📍</span>
                <span style={{ flex:1 }}>{addr}</span>
                {selectedSaved===addr && <span style={{ color:C.gold, fontSize:14 }}>✓</span>}
              </div>
            ))}
          </div>
        )}

        {tab === "new" && (
          <div style={{ marginBottom:20 }}>
            <label style={S.label}>Property Address</label>
            <input
              value={newAddress}
              onChange={e=>setNewAddress(e.target.value)}
              placeholder="e.g. 789 Pine Rd, Houston, TX 77001"
              style={S.input}
              autoFocus
            />
            <p style={{ margin:"8px 0 0", fontSize:11, color:C.textSoft }}>This address will be saved for future checkouts.</p>
          </div>
        )}

        <div style={{ display:"flex", gap:10 }}>
          <button onClick={handleConfirm} disabled={!canConfirm}
            style={{ ...S.btnPrimary, flex:1, padding:"12px", opacity:canConfirm?1:0.45 }}>
            Confirm Checkout
          </button>
          <button onClick={onCancel} style={{ ...S.ghost, padding:"12px 18px" }}>Cancel</button>
        </div>
      </div>
    </div>
  );
}

