// ADMIN VIEW
// ════════════════════════════════════════════════════════════════
function AdminView({ session, items, setItems, users, setUsers, rooms, setRooms, savedAddresses, setSavedAddresses, onLogout, db }) {
  const [tab, setTab] = useState("inventory");
  const [viewMode, setViewMode] = useState("grid");
  const [filter, setFilter] = useState("All");
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState(null);
  const [showItemForm, setShowItemForm] = useState(false);
  const [showUserForm, setShowUserForm] = useState(false);
  const [editItemId, setEditItemId] = useState(null);
  const [editUserId, setEditUserId] = useState(null);
  const [checkoutItemId, setCheckoutItemId] = useState(null);
  const [itemForm, setItemForm] = useState({ name:"", room:"Living Room", condition:"Good", notes:"", photo:null });
  const [userForm, setUserForm] = useState({ name:"", username:"", password:"", role:"worker" });
  const fileRef = useRef();

  const filtered = items.filter(it =>
    (filter==="All"||it.room===filter) &&
    it.name.toLowerCase().includes(search.toLowerCase())
  );

  const openAddItem = () => { setItemForm({ name:"", room:"Living Room", condition:"Good", notes:"", photo:null, qty:1 }); setEditItemId(null); setShowItemForm(true); };
  const openEditItem = (item) => { setItemForm({...item}); setEditItemId(item.id); setShowItemForm(true); };
  const saveItem = async () => {
    if (!itemForm.name.trim()) return;
    if (editItemId) {
      const existing = items.find(i=>i.id===editItemId);
      await db.updateItem(editItemId, {...itemForm, status:existing?.status||"in", log:existing?.log||[]});
      setItems(p=>p.map(it=>it.id===editItemId?{...itemForm,id:editItemId,status:it.status,log:it.log}:it));
    } else {
      const id="F"+String(Date.now()).slice(-6);
      const newItem = {...itemForm,id,status:"in",qty:itemForm.qty||1,log:[]};
      await db.addItem(newItem);
      setItems(p=>[...p,newItem]);
    }
    setShowItemForm(false);
  };
  const deleteItem = async (id) => {
    await db.deleteItem(id);
    setItems(p=>p.filter(it=>it.id!==id));
    setSelected(null);
  };

  const confirmCheckout = async (id, address) => {
    const ts = new Date().toLocaleString();
    const item = items.find(i=>i.id===id);
    const newLog = [...(item?.log||[]), { action:"Checked Out", by:session.user.name, at:ts, address }];
    await db.updateItem(id, { status:"out", address, log:newLog });
    if (address && !savedAddresses.includes(address)) {
      await db.addAddress(address);
      setSavedAddresses(prev => [address, ...prev].slice(0, 10));
    }
    setItems(prev => prev.map(it => it.id===id ? { ...it, status:"out", address, log:newLog } : it));
    setCheckoutItemId(null);
  };

  const markReturn = async (id) => {
    const ts = new Date().toLocaleString();
    const item = items.find(i=>i.id===id);
    const newLog = [...(item?.log||[]), { action:"Returned", by:session.user.name, at:ts }];
    await db.updateItem(id, { status:"in", address:null, log:newLog });
    setItems(prev => prev.map(it => it.id===id ? { ...it, status:"in", address:null, log:newLog } : it));
  };

  const handleAction = (id, newStatus) => {
    if (newStatus === "out") { setCheckoutItemId(id); return; }
    markReturn(id);
  };

  const handlePhoto = (e) => {
    const file = e.target.files[0]; if(!file) return;
    const r = new FileReader(); r.onload = ev => setItemForm(f=>({...f,photo:ev.target.result})); r.readAsDataURL(file);
  };

  const openAddUser = () => { setUserForm({ name:"", username:"", password:"", role:"worker" }); setEditUserId(null); setShowUserForm(true); };
  const openEditUser = (u) => { setUserForm({...u}); setEditUserId(u.id); setShowUserForm(true); };
  const saveUser = async () => {
    if (!userForm.username.trim()||!userForm.password.trim()) return;
    if (editUserId) {
      await db.updateUser(editUserId, userForm);
      setUsers(p=>p.map(u=>u.id===editUserId?{...userForm,id:editUserId}:u));
    } else {
      const newUser = {...userForm, id:"u"+Date.now()};
      await db.addUser(newUser);
      setUsers(p=>[...p, newUser]);
    }
    setShowUserForm(false);
  };

  const selItem = selected ? items.find(i=>i.id===selected.id) : null;

  const downloadQR = (item) => {
    const canvas = document.querySelector(`[data-qr="${item.id}"] canvas`);
    if (!canvas) return;
    const a = document.createElement("a"); a.download=`QR_${item.id}.png`; a.href=canvas.toDataURL(); a.click();
  };

  return (
    <div style={{ minHeight:"100vh", background:C.bg, fontFamily:"'Georgia', serif", color:C.text }}>
      <Header name={session.user.name} role="Admin" onLogout={onLogout}>
        <nav style={{ display:"flex", gap:6 }}>
          {[["inventory","Inventory"],["scan","Scan QR"],["users","Team"],["settings","Settings"]].map(([key,label])=>(
            <button key={key} onClick={()=>{ setTab(key); setSelected(null); }} style={{
              padding:"7px 18px", borderRadius:6, cursor:"pointer", fontSize:12, fontFamily:"'Georgia',serif",
              letterSpacing:"0.06em", border:`1px solid ${tab===key?C.charcoal:C.border}`,
              background: tab===key?C.charcoal:"transparent",
              color: tab===key?"#faf7f4":C.textMid,
            }}>{label}</button>
          ))}
        </nav>
      </Header>

      <div style={{ maxWidth:920, margin:"0 auto", padding:"24px 20px" }}>

        {/* ── INVENTORY ── */}
        {tab==="inventory" && !selItem && (
          <>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:20, flexWrap:"wrap", gap:12 }}>
              <div>
                <h2 style={{ margin:0, fontSize:18, fontWeight:700, letterSpacing:"-0.02em" }}>Furniture Inventory</h2>
                <p style={{ margin:"3px 0 0", fontSize:12, color:C.textMid }}>{items.length} items · {[...new Set(items.map(i=>i.room))].length} rooms</p>
              </div>
              <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                <SearchBar search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} compact rooms={rooms} />
                {["grid","list"].map(v=>(
                  <button key={v} onClick={()=>setViewMode(v)} style={{ padding:"8px 11px", borderRadius:6, border:`1px solid ${C.border}`, background:viewMode===v?C.charcoal:"transparent", color:viewMode===v?"#faf7f4":C.textMid, cursor:"pointer", fontSize:13 }}>
                    {v==="grid"?"⊞":"☰"}
                  </button>
                ))}
                <button onClick={openAddItem} style={S.btnGold}>+ Add Item</button>
              </div>
            </div>

            {viewMode==="grid" && (
              <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))", gap:14 }}>
                {filtered.map(item=>(
                  <div key={item.id} onClick={()=>setSelected(item)}
                    style={{ ...S.card, overflow:"hidden", cursor:"pointer", transition:"box-shadow .2s,border-color .2s" }}
                    onMouseEnter={e=>{ e.currentTarget.style.borderColor=C.gold; e.currentTarget.style.boxShadow="0 4px 20px rgba(0,0,0,0.08)"; }}
                    onMouseLeave={e=>{ e.currentTarget.style.borderColor=C.border; e.currentTarget.style.boxShadow="none"; }}>
                    <div style={{ height:130, background:item.photo?`url(${item.photo}) center/cover`:`linear-gradient(135deg,${C.bgDeep},${C.bg})`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:36 }}>
                      {!item.photo&&"🪑"}
                    </div>
                    <div style={{ padding:"12px 14px" }}>
                      <div style={{ fontSize:13, fontWeight:700, marginBottom:3, color:C.text }}>{item.name}</div>
                      <div style={{ fontSize:11, color:C.textMid, marginBottom:8 }}>{item.room}</div>
                      <div style={{ display:"flex", justifyContent:"space-between" }}>
                        <StatusBadge status={item.status} />
                        <CondBadge cond={item.condition} />
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {viewMode==="list" && (
              <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                {filtered.map(item=>(
                  <div key={item.id} onClick={()=>setSelected(item)}
                    style={{ ...S.card, padding:"12px 16px", display:"flex", alignItems:"center", gap:14, cursor:"pointer", transition:"border-color .2s" }}
                    onMouseEnter={e=>e.currentTarget.style.borderColor=C.gold}
                    onMouseLeave={e=>e.currentTarget.style.borderColor=C.border}>
                    <div style={{ width:44,height:44,borderRadius:6,background:item.photo?`url(${item.photo}) center/cover`:`linear-gradient(135deg,${C.bgDeep},${C.bg})`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0 }}>
                      {!item.photo&&"🪑"}
                    </div>
                    <div style={{ flex:1 }}>
                      <div style={{ fontSize:13, fontWeight:700 }}>{item.name}</div>
                      <div style={{ fontSize:11, color:C.textMid }}>{item.room}</div>
                    </div>
                    <StatusBadge status={item.status} />
                    <CondBadge cond={item.condition} />
                    <span style={{ fontSize:10, color:C.textSoft, fontFamily:"monospace" }}>{item.id}</span>
                  </div>
                ))}
              </div>
            )}
            {filtered.length===0 && <EmptyState />}
          </>
        )}

        {/* ── ITEM DETAIL (admin) ── */}
        {tab==="inventory" && selItem && (
          <div>
            <div style={{ display:"flex", gap:10, marginBottom:20, flexWrap:"wrap" }}>
              <button onClick={()=>setSelected(null)} style={{ ...S.ghost, fontSize:12 }}>← Back</button>
              <button onClick={()=>openEditItem(selItem)} style={S.btnGold}>Edit Item</button>
              <button onClick={()=>deleteItem(selItem.id)} style={{ padding:"8px 16px", borderRadius:6, cursor:"pointer", background:"transparent", border:`1px solid ${C.red}`, color:C.red, fontFamily:"'Georgia',serif", fontSize:13 }}>Delete</button>
            </div>
            <ItemDetailCard item={selItem} isWorker onAction={handleAction} onDownloadQR={()=>downloadQR(selItem)} />
          </div>
        )}

        {/* ── TEAM TAB ── */}
        {tab==="users" && (
          <div>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:20 }}>
              <div>
                <h2 style={{ margin:0, fontSize:18, fontWeight:700 }}>Team Members</h2>
                <p style={{ margin:"3px 0 0", fontSize:12, color:C.textMid }}>{users.length} accounts</p>
              </div>
              <button onClick={openAddUser} style={S.btnGold}>+ Add Worker</button>
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              {users.map(u=>(
                <div key={u.id} style={{ ...S.card, padding:"14px 18px", display:"flex", alignItems:"center", gap:14 }}>
                  <div style={{ width:42,height:42,borderRadius:"50%",background:`${C.gold}22`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,flexShrink:0,border:`1px solid ${C.goldLight}` }}>
                    {u.role==="admin"?"👑":"👷"}
                  </div>
                  <div style={{ flex:1 }}>
                    <div style={{ fontSize:14, fontWeight:700 }}>{u.name}</div>
                    <div style={{ fontSize:11, color:C.textMid }}>@{u.username} · <span style={{ color:u.role==="admin"?C.gold:C.textSoft, textTransform:"capitalize" }}>{u.role}</span></div>
                  </div>
                  {u.role!=="admin" ? (
                    <div style={{ display:"flex", gap:8 }}>
                      <button onClick={()=>openEditUser(u)} style={{ ...S.ghost, fontSize:12, padding:"6px 12px" }}>Edit</button>
                      <button onClick={async()=>{ await db.deleteUser(u.id); setUsers(p=>p.filter(x=>x.id!==u.id)); }} style={{ padding:"6px 12px", borderRadius:6, cursor:"pointer", background:"transparent", border:`1px solid ${C.red}`, color:C.red, fontSize:12, fontFamily:"'Georgia',serif" }}>Remove</button>
                    </div>
                  ) : <span style={{ fontSize:11, color:C.textSoft, fontStyle:"italic" }}>Protected</span>}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ── SCAN TAB ── */}
        {tab==="scan" && (
          <QRScanTab items={items} session={session} onAction={handleAction} savedAddresses={savedAddresses} onCheckout={(id,addr)=>confirmCheckout(id,addr)} />
        )}

        {/* ── SETTINGS TAB ── */}
        {tab==="settings" && (
          <SettingsTab rooms={rooms} setRooms={setRooms} items={items} db={db} />
        )}
      </div>

      {/* ── CHECKOUT MODAL (admin) ── */}
      {checkoutItemId && (
        <CheckoutModal
          itemName={items.find(i=>i.id===checkoutItemId)?.name}
          savedAddresses={savedAddresses}
          onConfirm={(addr) => confirmCheckout(checkoutItemId, addr)}
          onCancel={() => setCheckoutItemId(null)}
        />
      )}

      {/* ── ITEM FORM MODAL ── */}
      {showItemForm && (
        <Modal title={editItemId?"Edit Item":"Add Furniture"} onClose={()=>setShowItemForm(false)}>
          {[["Name","name","text","e.g. Oak Dining Table"],["Notes","notes","text","Optional notes"]].map(([l,k,,ph])=>(
            <div key={k} style={{ marginBottom:15 }}>
              <label style={S.label}>{l}</label>
              <input value={itemForm[k]} onChange={e=>setItemForm(f=>({...f,[k]:e.target.value}))} placeholder={ph} style={S.input} />
            </div>
          ))}
          <div style={{ marginBottom:15 }}>
            <label style={S.label}>Quantity</label>
            <input type="number" min="1" value={itemForm.qty||1} onChange={e=>setItemForm(f=>({...f,qty:Math.max(1,parseInt(e.target.value)||1)}))} style={S.input} />
          </div>
          <div style={{ marginBottom:15 }}>
            <label style={S.label}>Category / Room</label>
            <select value={itemForm.room} onChange={e=>setItemForm(f=>({...f,room:e.target.value}))} style={S.input}>
              {rooms.map(r=><option key={r}>{r}</option>)}
            </select>
          </div>
          <div style={{ marginBottom:15 }}>
            <label style={S.label}>Condition</label>
            <div style={{ display:"flex", gap:6 }}>
              {CONDITIONS.map(c=>(
                <button key={c} onClick={()=>setItemForm(f=>({...f,condition:c}))} style={{ flex:1, padding:"7px 4px", borderRadius:6, cursor:"pointer", fontFamily:"'Georgia',serif", fontSize:11, border:`1px solid ${itemForm.condition===c?conditionColor(c):C.border}`, background:itemForm.condition===c?conditionColor(c)+"22":"transparent", color:itemForm.condition===c?conditionColor(c):C.textMid }}>{c}</button>
              ))}
            </div>
          </div>
          <div style={{ marginBottom:22 }}>
            <label style={S.label}>Photo</label>
            <div onClick={()=>fileRef.current.click()} style={{ border:`2px dashed ${C.border}`, borderRadius:8, minHeight:80, display:"flex", alignItems:"center", justifyContent:"center", cursor:"pointer", color:C.textSoft, fontSize:13, background:itemForm.photo?`url(${itemForm.photo}) center/cover`:C.bgDeep }}>
              {!itemForm.photo&&"📷 Upload photo"}
            </div>
            <input ref={fileRef} type="file" accept="image/*" onChange={handlePhoto} style={{ display:"none" }} />
            {itemForm.photo && <button onClick={()=>setItemForm(f=>({...f,photo:null}))} style={{ background:"none",border:"none",color:C.red,cursor:"pointer",fontSize:12,fontFamily:"'Georgia',serif",marginTop:4 }}>Remove photo</button>}
          </div>
          <div style={{ display:"flex", gap:10 }}>
            <button onClick={saveItem} style={{ ...S.btnPrimary, flex:1, padding:"12px" }}>Save</button>
            <button onClick={()=>setShowItemForm(false)} style={{ ...S.ghost, padding:"12px 18px" }}>Cancel</button>
          </div>
        </Modal>
      )}

      {/* ── USER FORM MODAL ── */}
      {showUserForm && (
        <Modal title={editUserId?"Edit Worker":"Add Worker"} onClose={()=>setShowUserForm(false)}>
          {[["Full Name","name","text","e.g. Maria Lopez"],["Username","username","text","e.g. maria"],["Password","password","password","Min 6 characters"]].map(([l,k,t,ph])=>(
            <div key={k} style={{ marginBottom:15 }}>
              <label style={S.label}>{l}</label>
              <input type={t} value={userForm[k]} onChange={e=>setUserForm(f=>({...f,[k]:e.target.value}))} placeholder={ph} style={S.input} />
            </div>
          ))}
          <div style={{ display:"flex", gap:10, marginTop:8 }}>
            <button onClick={saveUser} style={{ ...S.btnPrimary, flex:1, padding:"12px" }}>Save</button>
            <button onClick={()=>setShowUserForm(false)} style={{ ...S.ghost, padding:"12px 18px" }}>Cancel</button>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ── Shared sub-components ──────────────────────────────────────
function Header({ name, role, onLogout, children }) {
  return (
    <div style={{ background:C.surface, borderBottom:`1px solid ${C.border}`, padding:"14px 24px" }}>
      <div style={{ maxWidth:920, margin:"0 auto", display:"flex", justifyContent:"space-between", alignItems:"center", flexWrap:"wrap", gap:12 }}>
        <Logo height={70} />
        <div style={{ display:"flex", alignItems:"center", gap:14, flexWrap:"wrap" }}>
          {children}
          <span style={{ fontSize:11, color:C.textSoft, letterSpacing:"0.04em" }}>{name} · {role}</span>
          <button onClick={onLogout} style={{ ...S.ghost, fontSize:12, padding:"6px 14px" }}>Sign Out</button>
        </div>
      </div>
    </div>
  );
}

function SearchBar({ search, setSearch, filter, setFilter, compact, rooms=[] }) {
  return (
    <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search…"
        style={{ ...S.input, flex:1, minWidth:compact?100:160 }} />
      <select value={filter} onChange={e=>setFilter(e.target.value)} style={{ ...S.input, width:"auto" }}>
        <option value="All">All Categories</option>
        {rooms.map(r=><option key={r}>{r}</option>)}
      </select>
    </div>
  );
}

function StatusBadge({ status }) {
  const out = status==="out";
  return <span style={{ fontSize:10, padding:"3px 8px", borderRadius:4, fontWeight:600, background:out?`${C.red}18`:`${C.green}18`, color:out?C.red:C.green, letterSpacing:"0.06em" }}>{out?"OUT":"IN"}</span>;
}
function CondBadge({ cond }) {
  return <span style={{ fontSize:10, padding:"3px 8px", borderRadius:4, fontWeight:600, background:conditionColor(cond)+"18", color:conditionColor(cond), letterSpacing:"0.04em" }}>{cond}</span>;
}

function ItemRow({ item, onClick }) {
  return (
    <div onClick={onClick} style={{ ...S.card, padding:"11px 15px", display:"flex", alignItems:"center", gap:13, cursor:"pointer", transition:"border-color .2s" }}
      onMouseEnter={e=>e.currentTarget.style.borderColor=C.gold}
      onMouseLeave={e=>e.currentTarget.style.borderColor=C.border}>
      <div style={{ width:44,height:44,borderRadius:6,background:item.photo?`url(${item.photo}) center/cover`:`linear-gradient(135deg,${C.bgDeep},${C.bg})`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0 }}>
        {!item.photo&&"🪑"}
      </div>
      <div style={{ flex:1 }}>
        <div style={{ fontSize:13, fontWeight:700, color:C.text }}>{item.name}</div>
        <div style={{ fontSize:11, color:C.textMid }}>{item.room}</div>
      </div>
      <span style={{ fontSize:11, color:C.textMid, fontWeight:600, minWidth:28, textAlign:"center" }}>×{item.qty||1}</span>
      <StatusBadge status={item.status} />
      <CondBadge cond={item.condition} />
    </div>
  );
}

